'use strict';

(function () {
	var STORAGE_KEY = 'todos-vanillajs';
	var ENTER_KEY = 'Enter';
	var ESCAPE_KEY = 'Escape';

	var newTodoInput = document.querySelector('.new-todo');
	var main = document.querySelector('.main');
	var footer = document.querySelector('.footer');
	var todoList = document.querySelector('.todo-list');
	var toggleAll = document.querySelector('.toggle-all');
	var todoCount = document.querySelector('.todo-count');
	var clearCompleted = document.querySelector('.clear-completed');
	var filterLinks = document.querySelectorAll('.filters a');

	var todos = load();
	var route = currentRoute();
	var rows = new Map();

	/**
	 * @planks("the visitor reloads the app")
	 * @planks-provisional("features/persistence.feature:Corrupt stored todos stop the app from starting")
	 */
	function load() {
		var raw = localStorage.getItem(STORAGE_KEY);
		return raw ? JSON.parse(raw) : [];
	}

	/**
	 * @planks("localStorage key {string} holds a todo with the title {string}")
	 */
	function save() {
		localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
	}

	/**
	 * @planks("the app is open with no stored todos")
	 * @planks-provisional("features/routing.feature:An unknown route falls back to showing all todos")
	 */
	function currentRoute() {
		var hash = location.hash;
		if (hash === '#/active' || hash === '#/completed') {
			return hash;
		}
		return '#/';
	}

	/**
	 * @planks("the visitor submits a new todo {string}")
	 */
	function addTodo(title) {
		todos.push({ id: Date.now() + Math.random(), title: title, completed: false });
	}

	/**
	 * @planks("the todo list contains {string}")
	 * @planks("the counter reads {string}")
	 * @planks("the todo list section is hidden")
	 * @planks("the footer is hidden")
	 * @planks("the clear completed control is hidden")
	 * @planks("the {string} filter link is selected")
	 * @planks("the mark-all control is checked")
	 * @planks-provisional("features/managing-todos.feature:A todo title with markup renders as plain text")
	 * @planks-provisional("features/routing.feature:A new todo added on the completed route stays hidden")
	 */
	function render() {
		var visible = todos.filter(function (todo) {
			if (route === '#/active') {
				return !todo.completed;
			}
			if (route === '#/completed') {
				return todo.completed;
			}
			return true;
		});

		rows.forEach(function (row, todo) {
			if (todos.indexOf(todo) === -1) {
				row.li.remove();
				rows.delete(todo);
			} else if (visible.indexOf(todo) === -1) {
				row.li.remove();
			}
		});

		visible.forEach(function (todo) {
			var row = rows.get(todo);
			if (!row) {
				row = createRow(todo);
				rows.set(todo, row);
			}
			row.li.classList.toggle('completed', todo.completed);
			row.toggle.checked = todo.completed;
			if (!row.li.classList.contains('editing')) {
				row.label.textContent = todo.title;
				row.edit.value = todo.title;
			}
			todoList.appendChild(row.li);
		});

		var hasTodos = todos.length > 0;
		main.hidden = !hasTodos;
		footer.hidden = !hasTodos;

		var activeCount = todos.filter(function (todo) {
			return !todo.completed;
		}).length;
		todoCount.innerHTML = '<strong>' + activeCount + '</strong> item' + (activeCount === 1 ? '' : 's') + ' left';

		toggleAll.checked = hasTodos && activeCount === 0;

		var hasCompleted = todos.some(function (todo) {
			return todo.completed;
		});
		clearCompleted.hidden = !hasCompleted;

		filterLinks.forEach(function (link) {
			link.classList.toggle('selected', link.getAttribute('href') === route);
		});
	}

	/**
	 * @planks("the todo list contains {string}")
	 */
	function createRow(todo) {
		var li = document.createElement('li');

		var view = document.createElement('div');
		view.className = 'view';

		var toggle = document.createElement('input');
		toggle.className = 'toggle';
		toggle.type = 'checkbox';

		var label = document.createElement('label');

		var destroy = document.createElement('button');
		destroy.className = 'destroy';

		view.appendChild(toggle);
		view.appendChild(label);
		view.appendChild(destroy);

		var edit = document.createElement('input');
		edit.className = 'edit';

		li.appendChild(view);
		li.appendChild(edit);

		/**
		 * @planks("the visitor completes {string}")
		 * @planks("the visitor reactivates {string}")
		 */
		toggle.addEventListener('change', function () {
			todo.completed = toggle.checked;
			update();
		});

		/**
		 * @planks("the visitor destroys {string}")
		 */
		destroy.addEventListener('click', function () {
			todos.splice(todos.indexOf(todo), 1);
			update();
		});

		/**
		 * @planks("the visitor starts editing {string}")
		 */
		label.addEventListener('dblclick', function () {
			li.classList.add('editing');
			edit.value = todo.title;
			edit.focus();
		});

		/**
		 * @planks("the visitor edits {string} to {string}")
		 * @planks("the visitor presses Escape")
		 * @planks-provisional("features/managing-todos.feature:A key other than Enter or Escape while editing keeps the edit open")
		 */
		edit.addEventListener('keydown', function (event) {
			if (event.key === ENTER_KEY) {
				commitEdit(todo, li, edit.value);
			} else if (event.key === ESCAPE_KEY) {
				li.classList.remove('editing');
				edit.value = todo.title;
			}
		});

		return { li: li, toggle: toggle, label: label, destroy: destroy, edit: edit };
	}

	/**
	 * @planks("the visitor edits {string} to {string}")
	 */
	function commitEdit(todo, li, value) {
		var title = value.trim();
		li.classList.remove('editing');
		if (title === '') {
			todos.splice(todos.indexOf(todo), 1);
		} else {
			todo.title = title;
		}
		update();
	}

	/**
	 * @planks("localStorage key {string} holds a todo with the title {string}")
	 */
	function update() {
		save();
		render();
	}

	/**
	 * @planks("the visitor submits a new todo {string}")
	 * @planks-provisional("features/managing-todos.feature:A key other than Enter in the new todo field adds nothing")
	 */
	newTodoInput.addEventListener('keydown', function (event) {
		if (event.key !== ENTER_KEY) {
			return;
		}
		var title = newTodoInput.value.trim();
		if (title === '') {
			return;
		}
		addTodo(title);
		newTodoInput.value = '';
		update();
	});

	/**
	 * @planks("the visitor marks all todos as complete")
	 */
	toggleAll.addEventListener('change', function () {
		todos.forEach(function (todo) {
			todo.completed = toggleAll.checked;
		});
		update();
	});

	/**
	 * @planks("the visitor clears completed todos")
	 */
	clearCompleted.addEventListener('click', function () {
		todos = todos.filter(function (todo) {
			return !todo.completed;
		});
		update();
	});

	/**
	 * @planks("the visitor opens the {string} route")
	 */
	window.addEventListener('hashchange', function () {
		route = currentRoute();
		render();
	});

	render();
})();

