'use strict';

const { World, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..', '..');

class TodoWorld extends World {
	async openApp(storage, hash) {
		this.window = new Window({ url: 'http://localhost/' + (hash || '') });
		const html = fs.readFileSync(path.join(ROOT, 'index.html'), 'utf8');
		this.window.document.write(html);
		this.document = this.window.document;
		try {
			const css = fs.readFileSync(path.join(ROOT, 'css', 'app.css'), 'utf8');
			const style = this.document.createElement('style');
			style.textContent = css;
			this.document.head.appendChild(style);
		} catch (error) {
			// css/app.css not present
		}
		if (storage) {
			for (const key of Object.keys(storage)) {
				this.window.localStorage.setItem(key, storage[key]);
			}
		}
		const appSource = fs.readFileSync(path.join(ROOT, 'js', 'app.js'), 'utf8');
		const run = new Function('window', 'document', 'localStorage', 'location', appSource);
		run(this.window, this.document, this.window.localStorage, this.window.location);
	}

	async reloadApp() {
		const storage = {};
		for (let i = 0; i < this.window.localStorage.length; i++) {
			const key = this.window.localStorage.key(i);
			storage[key] = this.window.localStorage.getItem(key);
		}
		const hash = this.window.location.hash;
		await this.openApp(storage, hash);
	}

	// Actor helpers, shared by Given and When steps.

	submitNewTodo(title) {
		const input = this.document.querySelector('.new-todo');
		input.value = title;
		input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
	}

	addTodo(title, completed) {
		this.submitNewTodo(title);
		if (completed) {
			this.toggleTodo(title);
		}
	}

	findItem(title) {
		const items = [...this.document.querySelectorAll('.todo-list li')];
		return items.find((li) => li.querySelector('.view label').textContent === title) || null;
	}

	toggleTodo(title) {
		const li = this.findItem(title);
		if (!li) {
			throw new Error('no todo titled ' + JSON.stringify(title));
		}
		li.querySelector('.toggle').click();
	}

